for(let i=gameTemplates.length-1;i>=0;i--)if(!gameTemplates[i].draft&&!['lumiere-wheel','nova-scratch','green-quiz'].includes(gameTemplates[i].id))gameTemplates.splice(i,1);
Object.assign(gameTemplates.find(t=>t.kind==='wheel'),{useCases:['팝업스토어','박람회','전시'],seasons:['가을']});
Object.assign(gameTemplates.find(t=>t.kind==='quiz'),{headline:'그린데이 제품을<br>얼마나 알고 있나요?',desc:'제품 퀴즈 3문제를 풀고 경품에 응모하는 이벤트'});
function defaultQuestions(){return [{question:'그린데이 신제품의 주원료는 무엇인가요?',options:['유기농 녹차','레몬','커피'],answer:0},{question:'신제품 한 병의 용량은 얼마인가요?',options:['200ml','350ml','500ml'],answer:1},{question:'그린데이가 사용하는 포장 소재는 무엇인가요?',options:['재생 플라스틱','일반 플라스틱','유리'],answer:0}]}
function editQuizQuestions(){return state.settings.quizQuestions||(state.settings.quizQuestions=defaultQuestions())}
function quizQuestions(){return state.settings.quizQuestions||defaultQuestions()}
const coreParse=parseGamePrompt;parseGamePrompt=function(p){const s=coreParse(p);s.probabilityNote='';if(s.kind==='quiz'){s.count=3;s.labels=[];s.questions=defaultQuestions();const n=p.match(/(\d+)\s*(?:개(?:의)?\s*질문|문제)/);if(n){const count=Math.max(1,Math.min(10,+n[1]));s.questions=Array.from({length:count},(_,i)=>defaultQuestions()[i]||{question:'질문 '+(i+1),options:['선택지 1','선택지 2','선택지 3'],answer:0});s.count=count}}return s};
const coreBuild=buildDraft;buildDraft=function(spec,id){coreBuild(spec,id);if(currentTemplate().kind==='quiz'){state.settings.quizQuestions=spec.questions||defaultQuestions();state.settings.rewards=[{name:'커피 상품권',quantity:'',probability:100,delivery:'모바일 상품권'}]}const copy=state.layers.find(l=>l.id==='copy'),button=state.layers.find(l=>l.id==='button');if(copy)copy.text=currentTemplate().kind==='scratch'?'카드를 긁고 당첨 결과를 확인하세요.':currentTemplate().kind==='quiz'?'퀴즈를 풀고 경품에 응모하세요.':'룰렛을 돌리고 선물을 확인하세요.';if(button)button.text=currentTemplate().kind==='scratch'?'카드 긁기':currentTemplate().kind==='quiz'?'정답 제출':'룰렛 돌리기'};
draftSummary=function(){return ''};
const coreTemplates=templates;templates=function(){return coreTemplates().replace(/<button[^>]*data-tplfilter="참여 유도"[^>]*>[\s\S]*?<\/button>/g,'')};
const coreProps=properties;properties=function(){let h=coreProps().replace(/<p class="mini-label">확률은 균등한 초안입니다\.[\s\S]*?<\/p>/g,'');if(state.layerId!=='game')return h;h=h.replace(/<div class="field"><label for="draft-choice-count">[\s\S]*$/,'').replace(/<div class="alert purple"[\s\S]*?<\/div>/,'');const kind=currentTemplate().kind;if(kind==='quiz'){const q=quizQuestions(),i=Math.min(state.quizEditingIndex||0,q.length-1),question=q[i];return h+`<div class="field"><label for="quiz-count">문제 수</label><input id="quiz-count" type="number" min="1" max="10" value="${q.length}"></div><div class="field"><label for="quiz-editing">편집할 문제</label><select id="quiz-editing">${q.map((_,j)=>`<option value="${j}" ${i===j?'selected':''}>문제 ${j+1}</option>`).join('')}</select></div><div class="field"><label for="quiz-question">질문</label><textarea id="quiz-question">${esc(question.question)}</textarea></div>${question.options.map((v,j)=>`<div class="field"><label for="quiz-option-${j}">선택지 ${j+1}</label><input id="quiz-option-${j}" data-quiz-option="${j}" value="${esc(v)}"></div>`).join('')}<div class="field"><label for="quiz-answer">정답</label><select id="quiz-answer">${question.options.map((_,j)=>`<option value="${j}" ${question.answer===j?'selected':''}>선택지 ${j+1}</option>`).join('')}</select></div>`}if(kind==='scratch')return h+`<div class="field"><label for="scratch-cover">가림막 문구</label><input id="scratch-cover" value="${esc(state.settings.scratchCover||'여기를 긁어주세요')}"></div><div class="field"><label for="scratch-result">당첨 카드 문구</label><input id="scratch-result" value="${esc(state.settings.scratchResult||'축하합니다!')}"></div><div class="field"><label for="scratch-prize">미리 볼 경품</label><select id="scratch-prize">${rewards().map((p,i)=>`<option value="${i}" ${state.settings.scratchPrize===i?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><button class="btn secondary wide" data-scratch-reveal>${state.scratchRevealed?'가림막 보기':'당첨 카드 보기'}</button>`;const labels=state.gameDraft?.labels||rewards().map(p=>p.name).concat('꽝');return h+`<div class="field"><label>룰렛 칸</label>${labels.map((name,i)=>`<div class="wheel-choice-row"><span>${i+1}</span><input data-wheel-choice="${i}" value="${esc(name)}" aria-label="${i+1}번 룰렛 칸 이름"></div>`).join('')}</div>`};
const coreSketch=gameSketch;gameSketch=function(t){const editing=t.id===state.selectedTemplate&&['editor','game-draft','prizes','brand-review','review'].includes(route());if(t.kind==='quiz'){const questions=editing?quizQuestions():defaultQuestions(),i=editing?Math.min(state.quizEditingIndex||0,questions.length-1):0,q=questions[i];return `<div class="sample-quiz"><span class="quiz-count">문제 ${i+1} / ${questions.length}</span><div class="quiz-question">${esc(q.question)}</div>${q.options.map((v,j)=>`<div class="quiz-option">${String.fromCharCode(65+j)}　${esc(v)}</div>`).join('')}</div>`}if(t.kind==='scratch'){const prize=editing?rewards()[state.settings.scratchPrize||0]?.name||'경품':'커피 상품권';return `<div class="scratch-card ${editing&&state.scratchRevealed?'revealed':''}"><div class="scratch-result"><strong>${esc(editing?state.settings.scratchResult||'축하합니다!':'축하합니다!')}</strong><span>${esc(prize)}</span></div><div class="scratch-cover">${esc(editing?state.settings.scratchCover||'여기를 긁어주세요':'여기를 긁어주세요')}</div></div>`}if(t.kind==='wheel'&&(!editing||!state.gameDraft)){const labels=editing?rewards().map(p=>p.name).concat('꽝'):['커피','쿠폰','선물','꽝','쿠폰','꽝'];return `<div class="draft-wheel gallery-wheel" style="background:conic-gradient(${labels.map((_,i)=>['var(--accent)','var(--stage)','#ead4ac','var(--paper)'][i%4]+' '+i*360/labels.length+'deg '+(i+1)*360/labels.length+'deg').join(',')})">${labels.map((s,i)=>`<span style="--angle:${(i+.5)*360/labels.length}deg">${s}</span>`).join('')}<b>GO</b></div>`}return coreSketch(t)};
const historyOperate=operate;operate=function(){return historyOperate().replace(/<a href="#workspace" class="text-link">브랜드 발송 이력 ↗<\/a>/,'<button class="text-link" data-send-history>브랜드 발송 이력</button>')};
state.sendHistory={event:'전체',status:'전체',page:1};
function sendingRows(){return allEventRows().filter(r=>r.brand.id===state.brandId&&r.flow.done.publish).flatMap(r=>{const total=r.e[0]==='루미에르 성수 팝업 룰렛'?854:r.e[0]==='루미에르 뷰티 위크'?386:0,failed=taskCounts(r).failed;return Array.from({length:total},(_,i)=>({event:r.e[0],recipient:'010-****-'+String(1000+i),prize:i%3===0?'할인 쿠폰':'커피 상품권',channel:i%3===0?'문자':'모바일 상품권',status:i<failed?'발송 실패':'발송 완료',date:(r.record.basic.end||'2026-10-16')+' '+String(10+i%8).padStart(2,'0')+':'+String(i%60).padStart(2,'0')}))})}
function sendingBody(){const all=sendingRows(),filter=state.sendHistory,rows=all.filter(r=>(filter.event==='전체'||r.event===filter.event)&&(filter.status==='전체'||r.status===filter.status)),pages=Math.max(1,Math.ceil(rows.length/20));filter.page=Math.min(filter.page,pages);const events=[...new Set(all.map(r=>r.event))];return `<div class="send-filters"><select id="send-event" aria-label="행사 필터"><option>전체</option>${events.map(e=>`<option ${e===filter.event?'selected':''}>${esc(e)}</option>`).join('')}</select><select id="send-status" aria-label="발송 상태 필터">${['전체','발송 완료','발송 실패'].map(e=>`<option ${e===filter.status?'selected':''}>${e}</option>`).join('')}</select><span class="mini-label">총 ${rows.length.toLocaleString()}건</span></div><div class="table-wrap send-table"><table><thead><tr><th>행사</th><th>수신 번호</th><th>경품</th><th>채널</th><th>발송 상태</th><th>발송 일시</th></tr></thead><tbody>${rows.slice((filter.page-1)*20,filter.page*20).map(r=>`<tr><td>${esc(r.event)}</td><td>${r.recipient}</td><td>${r.prize}</td><td>${r.channel}</td><td>${pill(r.status,r.status==='발송 실패'?'review':'')}</td><td>${r.date}</td></tr>`).join('')||'<tr><td colspan="6">발송 이력이 없습니다.</td></tr>'}</tbody></table></div><div class="send-pagination"><button class="btn secondary" data-send-page="-1" ${filter.page===1?'disabled':''}>이전</button><span>${filter.page} / ${pages}</span><button class="btn secondary" data-send-page="1" ${filter.page===pages?'disabled':''}>다음</button></div>`}
function openSendingHistory(){state.sendHistory={event:'전체',status:'전체',page:1};app.insertAdjacentHTML('beforeend',`<div class="modal-overlay send-overlay"><section class="modal send-history-modal" role="dialog" aria-modal="true" aria-labelledby="send-history-title"><div class="panel-head"><div><h2 id="send-history-title">브랜드 발송 이력</h2><p class="mini-label">${esc(currentBrand().name)} · 시연 데이터</p></div><button data-close-send aria-label="닫기">${uiIcon('close')}</button></div><div id="send-history-body">${sendingBody()}</div></section></div>`);bindSendHistory();document.querySelector('[data-close-send]')?.focus?.()}
function closeSendingHistory(){document.querySelector('.send-overlay')?.remove();app.querySelector('[data-send-history]')?.focus()}
function bindSendHistory(){const close=document.querySelector('[data-close-send]');if(close)close.onclick=closeSendingHistory;for(const [id,key] of [['send-event','event'],['send-status','status']]){const input=document.getElementById(id);if(input)input.onchange=()=>{state.sendHistory[key]=input.value;state.sendHistory.page=1;refreshSending()}}app.querySelectorAll('[data-send-page]').forEach(n=>n.onclick=()=>{state.sendHistory.page+=+n.dataset.sendPage;refreshSending()})}
function refreshSending(){document.getElementById('send-history-body').innerHTML=sendingBody();bindSendHistory()}
document.addEventListener('keydown',e=>{if(!document.getElementById('send-history-body'))return;if(e.key==='Escape')closeSendingHistory();if(e.key==='Tab'){const nodes=[...document.querySelectorAll('.send-history-modal button:not(:disabled),.send-history-modal select')],first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
const focusedBind=bind;bind=function(){focusedBind();app.querySelectorAll('[data-send-history]').forEach(n=>n.onclick=openSendingHistory);const paint=()=>{invalidateApproval();document.getElementById('layer-canvas').innerHTML=layerCanvas();bindStudio()};const question=document.getElementById('quiz-question'),index=Math.min(state.quizEditingIndex||0,(state.settings.quizQuestions||defaultQuestions()).length-1);if(question)question.oninput=()=>{editQuizQuestions()[index].question=question.value;paint()};app.querySelectorAll('[data-quiz-option]').forEach(n=>n.oninput=()=>{editQuizQuestions()[index].options[+n.dataset.quizOption]=n.value;paint()});const answer=document.getElementById('quiz-answer');if(answer)answer.onchange=()=>{editQuizQuestions()[index].answer=+answer.value;invalidateApproval()};const editing=document.getElementById('quiz-editing');if(editing)editing.onchange=()=>{state.quizEditingIndex=+editing.value;render()};const count=document.getElementById('quiz-count');if(count)count.onchange=()=>{const n=Math.max(1,Math.min(10,+count.value||1));state.settings.quizQuestions=Array.from({length:n},(_,i)=>quizQuestions()[i]||{question:'질문 '+(i+1),options:['선택지 1','선택지 2','선택지 3'],answer:0});state.quizEditingIndex=0;invalidateApproval();render()};for(const [id,key] of [['scratch-cover','scratchCover'],['scratch-result','scratchResult'],['scratch-prize','scratchPrize']]){const input=document.getElementById(id);if(input)input.oninput=()=>{state.settings[key]=id==='scratch-prize'?+input.value:input.value;paint()}}app.querySelectorAll('[data-scratch-reveal]').forEach(n=>n.onclick=()=>{state.scratchRevealed=!state.scratchRevealed;render()})};
const typedCanvas=layerCanvas;layerCanvas=function(){let h=typedCanvas();if(state.studioPage==='게임'){const kind=currentTemplate().kind;if(kind==='scratch')h=h.replace('게임 시작하기','카드 긁기');if(kind==='quiz')h=h.replace('퀴즈 시작하기','정답 제출')}return h};
const focusedOpen=openWorkspaceEvent;openWorkspaceEvent=function(n){state.scratchRevealed=false;state.quizEditingIndex=0;focusedOpen(n)};
